INSERT INTO `destinations` (`id`, `slug`, `name`, `description`, `short_desc`, `type`, `moods`, `seasons`, `open_hours`, `cost`, `stay_capacity`, `highlight`, `checkin_tip`, `best_time`, `lat`, `lng`, `map_x`, `map_y`, `radius_meter`, `cover_image`, `gallery`, `audio_url`, `video_url`, `story`, `zen_walk_desc`, `qr_code_url`, `qr_secret`, `points`, `is_hub`, `is_active`, `sort_order`, `created_at`, `updated_at`) VALUES ('197950da-4b4d-44d3-9058-f7f8e0bddfe2', 'world-farm-the-gioi-nong-trai', 'World Farm - Thế giới nông trại', 'Tọa lạc tại xã Bình Lợi, huyện Bình Chánh, World Farm – Thế giới nông trại là điểm đến sinh thái kết hợp giữa giáo dục trải nghiệm và vui chơi ngoài trời, mang đến cơ hội để du khách khám phá cuộc sống nông nghiệp theo cách gần gũi và sinh động. Với không gian xanh rộng lớn, nông trại được thiết kế như một "lớp học giữa thiên nhiên", nơi mọi lứa tuổi đều có thể tìm hiểu về môi trường, cây trồng và nguồn gốc của thực phẩm.\n\nĐến với World Farm, du khách sẽ được hóa thân thành những người nông dân thực thụ thông qua nhiều hoạt động như trồng và chăm sóc cây, thu hoạch nông sản, cho vật nuôi ăn, làm bánh, chế biến nông sản và tham gia các trò chơi dân gian. Những trải nghiệm thực tế này không chỉ mang lại niềm vui mà còn giúp nâng cao ý thức về nông nghiệp bền vững, bảo vệ môi trường và giá trị của lao động.\n\nKhông chỉ là điểm tham quan, World Farm còn là nơi gắn kết gia đình, trường học và cộng đồng thông qua các chương trình ngoại khóa, dã ngoại và giáo dục kỹ năng sống. Giữa không gian xanh mát của vùng quê Bình Lợi, du khách sẽ có cơ hội tận hưởng bầu không khí trong lành, thư giãn giữa thiên nhiên và lưu giữ những kỷ niệm đáng nhớ trong hành trình khám phá du lịch sinh thái Bình Chánh.', 'Trải nghiệm hóa thân thành người nông dân, khám phá nông nghiệp xanh và tận hưởng những hoạt động giáo dục, vui chơi giữa không gian thiên nhiên trong lành.', 'nature', '[]', '[]', '07:00 - 18:00', 'Tùy theo chương trình trải nghiệm', 'none', 'Trải nghiệm hóa thân thành người nông dân, khám phá nông nghiệp xanh và tận hưởng những hoạt động giáo dục, vui chơi giữa không gian thiên nhiên trong lành.', 'Hãy chụp ảnh tại điểm này!', 'Quanh năm', '10.7533608', '106.4795437', 50, 50, 100, 'data:image/jpeg;base64,', NULL, NULL, NULL, 'Tọa lạc tại xã Bình Lợi, huyện Bình Chánh, World Farm – Thế giới nông trại là điểm đến sinh thái kết hợp giữa giáo dục trải nghiệm và vui chơi ngoài trời, mang đến cơ hội để du khách khám phá cuộc sống nông nghiệp theo cách gần gũi và sinh động. Với không gian xanh rộng lớn, nông trại được thiết kế như một "lớp học giữa thiên nhiên", nơi mọi lứa tuổi đều có thể tìm hiểu về môi trường, cây trồng và nguồn gốc của thực phẩm.\n\nĐến với World Farm, du khách sẽ được hóa thân thành những người nông dân thực thụ thông qua nhiều hoạt động như trồng và chăm sóc cây, thu hoạch nông sản, cho vật nuôi ăn, làm bánh, chế biến nông sản và tham gia các trò chơi dân gian. Những trải nghiệm thực tế này không chỉ mang lại niềm vui mà còn giúp nâng cao ý thức về nông nghiệp bền vững, bảo vệ môi trường và giá trị của lao động.\n\nKhông chỉ là điểm tham quan, World Farm còn là nơi gắn kết gia đình, trường học và cộng đồng thông qua các chương trình ngoại khóa, dã ngoại và giáo dục kỹ năng sống. Giữa không gian xanh mát của vùng quê Bình Lợi, du khách sẽ có cơ hội tận hưởng bầu không khí trong lành, thư giãn giữa thiên nhiên và lưu giữ những kỷ niệm đáng nhớ trong hành trình khám phá du lịch sinh thái Bình Chánh.', NULL, NULL, 'SECURE_WORLD-FARM-THE-GIOI-NONG-TRAI', 70, 0, 1, 99, '2026-06-21 03:45:52', '2026-06-21 04:07:23');
INSERT INTO `destinations` (`id`, `slug`, `name`, `description`, `short_desc`, `type`, `moods`, `seasons`, `open_hours`, `cost`, `stay_capacity`, `highlight`, `checkin_tip`, `best_time`, `lat`, `lng`, `map_x`, `map_y`, `radius_meter`, `cover_image`, `gallery`, `audio_url`, `video_url`, `story`, `zen_walk_desc`, `qr_code_url`, `qr_secret`, `points`, `is_hub`, `is_active`, `sort_order`, `created_at`, `updated_at`) VALUES ('20716b9e-784d-4ff1-ada1-28e9faee8696', 'vuon-phong-lan-ngoc-dan-vy', 'Vườn Phong Lan Ngọc Đan Vy', 'Các vườn lan tại khu vực ngoại thành TP.HCM không chỉ là nơi nuôi trồng và chăm sóc hoa lan mà còn trở thành điểm du lịch sinh thái được nhiều người yêu thích. Với hàng trăm chậu lan đủ màu sắc, hương thơm và chủng loại khác nhau, nơi đây mang đến không gian gần gũi thiên nhiên, yên bình và đầy sức sống.\nDu khách khi đến tham quan có thể tìm hiểu về quy trình chăm sóc lan, khám phá các giống lan quý và tận hưởng bầu không khí trong lành giữa những giàn hoa rực rỡ. Nhiều vườn lan còn kết hợp khu cà phê, tiểu cảnh và không gian check-in, tạo nên trải nghiệm thư giãn nhẹ nhàng, phù hợp cho gia đình, nhóm bạn hoặc những người yêu thích thiên nhiên và nghệ thuật cây cảnh.', 'Trải nghiệm không gian sinh thái ngập tràn sắc hoa, khám phá những giống lan độc đáo và tận hưởng vẻ đẹp yên bình giữa thiên nhiên xanh mát.', 'park', '[]', '["summer","winter"]', '07:00 - 18:00', 'Miễn phí', 'none', 'Vườn lan là điểm tham quan sinh thái nổi bật với không gian xanh mát, trưng bày nhiều giống lan đa dạng, phù hợp cho hoạt động tham quan, chụp ảnh và thư giãn cuối tuần.', 'Hãy chụp ảnh tại điểm này!', 'Quanh năm', '10.6572993', '106.5804351', 50, 50, 100, 'data:image/png;base64,', NULL, NULL, NULL, 'Các vườn lan tại khu vực ngoại thành TP.HCM không chỉ là nơi nuôi trồng và chăm sóc hoa lan mà còn trở thành điểm du lịch sinh thái được nhiều người yêu thích. Với hàng trăm chậu lan đủ màu sắc, hương thơm và chủng loại khác nhau, nơi đây mang đến không gian gần gũi thiên nhiên, yên bình và đầy sức sống.\r\nDu khách khi đến tham quan có thể tìm hiểu về quy trình chăm sóc lan, khám phá các giống lan quý và tận hưởng bầu không khí trong lành giữa những giàn hoa rực rỡ. Nhiều vườn lan còn kết hợp khu cà phê, tiểu cảnh và không gian check-in, tạo nên trải nghiệm thư giãn nhẹ nhàng, phù hợp cho gia đình, nhóm bạn hoặc những người yêu thích thiên nhiên và nghệ thuật cây cảnh.', '', NULL, 'SECURE_VUON-LAN', 30, 0, 1, 99, '2026-05-20 11:20:00', '2026-06-21 03:41:28');
INSERT INTO `destinations` (`id`, `slug`, `name`, `description`, `short_desc`, `type`, `moods`, `seasons`, `open_hours`, `cost`, `stay_capacity`, `highlight`, `checkin_tip`, `best_time`, `lat`, `lng`, `map_x`, `map_y`, `radius_meter`, `cover_image`, `gallery`, `audio_url`, `video_url`, `story`, `zen_walk_desc`, `qr_code_url`, `qr_secret`, `points`, `is_hub`, `is_active`, `sort_order`, `created_at`, `updated_at`) VALUES ('27d4d05c-3d48-4d05-922b-752cf22b3a3c', 'vuon-dua', 'Vườn dừa', 'Nằm tại xã Bình Lợi, huyện Bình Chánh, vườn dừa mang đậm vẻ đẹp mộc mạc của miền quê Nam Bộ giữa lòng thành phố đang phát triển. Những hàng dừa xanh cao vút trải dài dọc theo các tuyến đường và kênh rạch tạo nên khung cảnh yên bình, thoáng đãng và gần gũi thiên nhiên. Đây không chỉ là nơi canh tác nông nghiệp của người dân địa phương mà còn dần trở thành điểm tham quan, trải nghiệm được nhiều du khách yêu thích khi muốn tìm kiếm không gian thư giãn cuối tuần.\nĐến với vườn dừa Bình Lợi, du khách có thể cảm nhận nhịp sống chậm rãi của vùng ngoại thành, tận hưởng bầu không khí trong lành và khám phá nét văn hóa nông nghiệp đặc trưng của Bình Chánh. Hình ảnh những vườn dừa xanh mát cũng góp phần tạo nên dấu ấn riêng cho du lịch sinh thái Bình Lợi – nơi vẫn giữ được vẻ đẹp giản dị, thanh bình giữa đô thị hiện đại.', 'Trải nghiệm không gian sinh thái xanh mát dưới những hàng dừa đặc trưng, tận hưởng bầu không khí trong lành và khám phá vẻ đẹp bình yên của vùng quê Bình Lợi.', 'park', '[]', '["summer"]', '08:00 - 17:00', 'Miễn phí', 'none', 'Vườn dừa Bình Lợi là điểm du lịch sinh thái đặc trưng của xã Bình Lợi, huyện Bình Chánh với không gian xanh mát, hàng dừa trải dài và nét bình yên của vùng ngoại thành TP.HCM.', 'Hãy chụp ảnh tại điểm này!', 'Quanh năm', '10.7636625', '106.4953031', 50, 50, 100, 'data:image/png;base64,', NULL, NULL, NULL, 'Nằm tại xã Bình Lợi, huyện Bình Chánh, vườn dừa mang đậm vẻ đẹp mộc mạc của miền quê Nam Bộ giữa lòng thành phố đang phát triển. Những hàng dừa xanh cao vút trải dài dọc theo các tuyến đường và kênh rạch tạo nên khung cảnh yên bình, thoáng đãng và gần gũi thiên nhiên. Đây không chỉ là nơi canh tác nông nghiệp của người dân địa phương mà còn dần trở thành điểm tham quan, trải nghiệm được nhiều du khách yêu thích khi muốn tìm kiếm không gian thư giãn cuối tuần.\r\nĐến với vườn dừa Bình Lợi, du khách có thể cảm nhận nhịp sống chậm rãi của vùng ngoại thành, tận hưởng bầu không khí trong lành và khám phá nét văn hóa nông nghiệp đặc trưng của Bình Chánh. Hình ảnh những vườn dừa xanh mát cũng góp phần tạo nên dấu ấn riêng cho du lịch sinh thái Bình Lợi – nơi vẫn giữ được vẻ đẹp giản dị, thanh bình giữa đô thị hiện đại.', '', NULL, 'SECURE_VUON-DUA', 40, 0, 1, 99, '2026-05-20 11:35:44', '2026-06-21 03:38:59');
INSERT INTO `destinations` (`id`, `slug`, `name`, `description`, `short_desc`, `type`, `moods`, `seasons`, `open_hours`, `cost`, `stay_capacity`, `highlight`, `checkin_tip`, `best_time`, `lat`, `lng`, `map_x`, `map_y`, `radius_meter`, `cover_image`, `gallery`, `audio_url`, `video_url`, `story`, `zen_walk_desc`, `qr_code_url`, `qr_secret`, `points`, `is_hub`, `is_active`, `sort_order`, `created_at`, `updated_at`) VALUES ('311e3aac-9615-4627-9bd5-1040daa693a0', 'tu-vien-kim-cang', 'Tu viện Kim Cang', '', '', 'temple', '[]', '[]', '07:00 - 18:00', 'Miễn phí', 'none', '', 'Hãy chụp ảnh tại điểm này!', 'Quanh năm', '10.7500000', '106.5400000', 50, 50, 100, '/images/placeholder.jpg', NULL, NULL, NULL, '', NULL, NULL, 'SECURE_TU-VIEN-KIM-CANG', 80, 0, 1, 99, '2026-06-21 18:57:09', '2026-06-21 18:57:09');
INSERT INTO `destinations` (`id`, `slug`, `name`, `description`, `short_desc`, `type`, `moods`, `seasons`, `open_hours`, `cost`, `stay_capacity`, `highlight`, `checkin_tip`, `best_time`, `lat`, `lng`, `map_x`, `map_y`, `radius_meter`, `cover_image`, `gallery`, `audio_url`, `video_url`, `story`, `zen_walk_desc`, `qr_code_url`, `qr_secret`, `points`, `is_hub`, `is_active`, `sort_order`, `created_at`, `updated_at`) VALUES ('3da8416a-0320-4d5e-ae14-cd50fb34ac0d', 'ueh-co-so-b', 'UEH - Cơ sở B', 'UEH - Cơ sở B là một trong những cơ sở quan trọng của Đại học Kinh tế Thành phố Hồ Chí Minh (UEH), phục vụ công tác đào tạo, nghiên cứu và phát triển nguồn nhân lực chất lượng cao. Với hệ thống giảng đường hiện đại, thư viện, phòng máy tính và không gian học tập mở, cơ sở đáp ứng nhu cầu học tập của hàng nghìn sinh viên mỗi năm.\n\nKhông chỉ là nơi diễn ra các giờ học trên lớp, UEH - Cơ sở B còn là trung tâm của nhiều hoạt động ngoại khóa, hội thảo học thuật, cuộc thi chuyên môn và các chương trình giao lưu với doanh nghiệp. Đây là môi trường giúp sinh viên phát triển toàn diện về kiến thức, kỹ năng nghề nghiệp và tư duy đổi mới sáng tạo.\n\nTrong nhiều năm qua, cơ sở đã chứng kiến hành trình học tập, nghiên cứu và trưởng thành của nhiều thế hệ sinh viên UEH. Những không gian quen thuộc như giảng đường, thư viện, khu tự học và sân trường đã trở thành những dấu ấn đáng nhớ trong quãng đời đại học của mỗi sinh viên.\n\nNgày nay, UEH - Cơ sở B tiếp tục được đầu tư, nâng cấp cơ sở vật chất và ứng dụng công nghệ số nhằm mang đến môi trường học tập hiện đại, thân thiện và bền vững, góp phần thực hiện mục tiêu trở thành đại học đa ngành, thông minh và có tầm ảnh hưởng trong khu vực.', 'UEH - Cơ sở B là một trong những cơ sở đào tạo chính của Đại học Kinh tế Thành phố Hồ Chí Minh (UEH), nơi diễn ra nhiều hoạt động học tập, nghiên cứu khoa học, sự kiện học thuật và hoạt động sinh viên trong môi trường giáo dục hiện đại.', 'craft', '[]', '[]', '07:00 - 18:00', 'Miễn phí', 'none', 'UEH - Cơ sở B là một trong những cơ sở đào tạo chính của Đại học Kinh tế Thành phố Hồ Chí Minh (UEH), nơi diễn ra nhiều hoạt động học tập, nghiên cứu khoa học, sự kiện học thuật và hoạt động sinh viên trong môi trường giáo dục hiện đại.', 'Hãy chụp ảnh tại điểm này!', 'Quanh năm', '10.7610532', '106.6683580', 50, 50, 100, 'data:image/jpeg;base64,', NULL, NULL, NULL, 'UEH - Cơ sở B là một trong những cơ sở quan trọng của Đại học Kinh tế Thành phố Hồ Chí Minh (UEH), phục vụ công tác đào tạo, nghiên cứu và phát triển nguồn nhân lực chất lượng cao. Với hệ thống giảng đường hiện đại, thư viện, phòng máy tính và không gian học tập mở, cơ sở đáp ứng nhu cầu học tập của hàng nghìn sinh viên mỗi năm.\n\nKhông chỉ là nơi diễn ra các giờ học trên lớp, UEH - Cơ sở B còn là trung tâm của nhiều hoạt động ngoại khóa, hội thảo học thuật, cuộc thi chuyên môn và các chương trình giao lưu với doanh nghiệp. Đây là môi trường giúp sinh viên phát triển toàn diện về kiến thức, kỹ năng nghề nghiệp và tư duy đổi mới sáng tạo.\n\nTrong nhiều năm qua, cơ sở đã chứng kiến hành trình học tập, nghiên cứu và trưởng thành của nhiều thế hệ sinh viên UEH. Những không gian quen thuộc như giảng đường, thư viện, khu tự học và sân trường đã trở thành những dấu ấn đáng nhớ trong quãng đời đại học của mỗi sinh viên.\n\nNgày nay, UEH - Cơ sở B tiếp tục được đầu tư, nâng cấp cơ sở vật chất và ứng dụng công nghệ số nhằm mang đến môi trường học tập hiện đại, thân thiện và bền vững, góp phần thực hiện mục tiêu trở thành đại học đa ngành, thông minh và có tầm ảnh hưởng trong khu vực.', NULL, NULL, 'SECURE_UEH-CO-SO-B', 100, 0, 1, 99, '2026-06-20 11:14:12', '2026-06-20 20:49:04');
INSERT INTO `destinations` (`id`, `slug`, `name`, `description`, `short_desc`, `type`, `moods`, `seasons`, `open_hours`, `cost`, `stay_capacity`, `highlight`, `checkin_tip`, `best_time`, `lat`, `lng`, `map_x`, `map_y`, `radius_meter`, `cover_image`, `gallery`, `audio_url`, `video_url`, `story`, `zen_walk_desc`, `qr_code_url`, `qr_secret`, `points`, `is_hub`, `is_active`, `sort_order`, `created_at`, `updated_at`) VALUES ('3ec7a849-930c-42c1-897b-57238908061e', 'lang-nghe-nhang-truyen-thong', 'Làng nghề nhang truyền thống', 'Làng nghề nhang truyền thống là nơi lưu giữ một trong những nghề thủ công lâu đời của người Việt, gắn bó với đời sống văn hóa và tín ngưỡng qua nhiều thế hệ. Từ khâu chọn nguyên liệu, se tăm, nhuộm chân nhang đến phơi khô đều được thực hiện hoàn toàn bằng đôi bàn tay khéo léo của những người thợ lành nghề. Hương thơm dịu nhẹ của nhang hòa cùng sắc đỏ, vàng rực rỡ của những bó nhang phơi dưới nắng tạo nên khung cảnh vừa bình dị, vừa trở thành nét đẹp đặc trưng của làng nghề truyền thống.\n\nKhông chỉ là nghề mưu sinh, làm nhang còn mang ý nghĩa tâm linh sâu sắc, gắn liền với phong tục thờ cúng tổ tiên, các dịp lễ Tết và đời sống tinh thần của người Việt. Qua từng nén nhang, người thợ gửi gắm sự tỉ mỉ, lòng thành kính và niềm tự hào về nghề truyền thống đã được gìn giữ qua nhiều thế hệ.\n\nĐến với làng nghề nhang truyền thống, du khách sẽ có cơ hội trực tiếp quan sát quy trình sản xuất, tự tay trải nghiệm các công đoạn làm nhang, tìm hiểu câu chuyện về nghề thủ công lâu đời và lưu giữ những bức ảnh ấn tượng giữa không gian rực rỡ sắc màu. Đây không chỉ là hành trình khám phá văn hóa mà còn là dịp để cảm nhận những giá trị truyền thống vẫn đang được gìn giữ và phát huy tại Bình Lợi.', 'Trải nghiệm nghề làm nhang thủ công truyền thống, khám phá nét đẹp văn hóa làng nghề và tự tay tạo nên những nén nhang mang đậm bản sắc Việt.', 'craft', '[]', '["spring","autumn"]', '07:00 - 18:00', '50.000đ (trải nghiệm làm nhang)', 'none', 'Làng nghề nhang truyền thống là nơi lưu giữ nét đẹp thủ công lâu đời với hình ảnh những bó nhang đầy màu sắc, phản ánh giá trị văn hóa và đời sống lao động của người dân địa phương.', 'Hãy chụp ảnh tại điểm này!', 'Quanh năm', '10.7525939', '106.4828935', 50, 50, 100, 'data:image/png;base64,', NULL, NULL, NULL, 'Làng nghề nhang truyền thống gắn liền với nghề làm nhang thủ công đã tồn tại qua nhiều thế hệ. Từ khâu chọn nguyên liệu, se tăm, nhuộm chân nhang đến phơi khô đều được thực hiện tỉ mỉ bởi đôi bàn tay khéo léo của người thợ. Hương thơm dịu nhẹ của nhang cùng sắc đỏ, vàng rực rỡ tạo nên khung cảnh đặc trưng vừa mộc mạc vừa đậm bản sắc văn hóa Việt Nam.\r\nKhông chỉ đơn thuần là một nghề mưu sinh, làm nhang còn mang ý nghĩa tâm linh sâu sắc trong đời sống người Việt, gắn với phong tục thờ cúng tổ tiên và các dịp lễ truyền thống. Ngày nay, nhiều làng nghề đã trở thành điểm tham quan hấp dẫn, giúp du khách trải nghiệm quy trình làm nhang, tìm hiểu giá trị văn hóa lâu đời và lưu lại những khoảnh khắc đẹp giữa không gian đậm chất truyền thống.', '', NULL, 'SECURE_LANG-NGHE-NHANG-TRUYEN-THONG', 40, 0, 1, 99, '2026-05-20 11:23:50', '2026-06-21 03:43:08');
INSERT INTO `destinations` (`id`, `slug`, `name`, `description`, `short_desc`, `type`, `moods`, `seasons`, `open_hours`, `cost`, `stay_capacity`, `highlight`, `checkin_tip`, `best_time`, `lat`, `lng`, `map_x`, `map_y`, `radius_meter`, `cover_image`, `gallery`, `audio_url`, `video_url`, `story`, `zen_walk_desc`, `qr_code_url`, `qr_secret`, `points`, `is_hub`, `is_active`, `sort_order`, `created_at`, `updated_at`) VALUES ('612d3926-6d5f-11f1-9faa-1a708c0034e1', 'xuong-nhang-minh', 'Xưởng Nhang Truyền Thống', 'Làng nghề làm nhang tại Bình Lợi đã có tuổi đời hàng chục năm. Đến đây, du khách sẽ được tận mắt chứng kiến quy trình làm nhang thủ công, từ khâu trộn bột, se nhang đến phơi nhang dưới nắng mặt trời, tạo nên những dải lụa đỏ vàng rực rỡ khắp cả một vùng quê. Đây là nơi lưu giữ hơi thở của văn hóa truyền thống giữa lòng Sài Gòn hiện đại.', 'Làng nghề nhang rực rỡ sắc màu di sản.', 'craft', '["trai_nghiem","kham_pha"]', 'spring, summer', '08:00 - 17:00', '50.000đ - 100.000đ (bao gồm phí trải nghiệm)', 'none', 'Trải nghiệm workshop tự tay se nhang và cảm nhận mùi hương thảo mộc.', 'Hãy chụp ảnh tại điểm này!', 'Ngày nắng đẹp (để ngắm phơi nhang)', '10.7512000', '106.5423000', 50, 50, 100, '/images/xuong-nhang-1.png', NULL, NULL, NULL, 'Làng nghề làm nhang tại Bình Lợi đã có tuổi đời hàng chục năm. Đến đây, du khách sẽ được tận mắt chứng kiến quy trình làm nhang thủ công, từ khâu trộn bột, se nhang đến phơi nhang dưới nắng mặt trời, tạo nên những dải lụa đỏ vàng rực rỡ khắp cả một vùng quê. Đây là nơi lưu giữ hơi thở của văn hóa truyền thống giữa lòng Sài Gòn hiện đại.', NULL, NULL, 'SECURE_XUONG-NHANG-MINH', 200, 0, 1, 0, '2026-06-21 03:53:04', '2026-06-21 18:39:05');
INSERT INTO `destinations` (`id`, `slug`, `name`, `description`, `short_desc`, `type`, `moods`, `seasons`, `open_hours`, `cost`, `stay_capacity`, `highlight`, `checkin_tip`, `best_time`, `lat`, `lng`, `map_x`, `map_y`, `radius_meter`, `cover_image`, `gallery`, `audio_url`, `video_url`, `story`, `zen_walk_desc`, `qr_code_url`, `qr_secret`, `points`, `is_hub`, `is_active`, `sort_order`, `created_at`, `updated_at`) VALUES ('614ed6c2-6d5f-11f1-9faa-1a708c0034e1', 'cau-chu-z', 'Cầu Chữ U / Cầu Bình Lợi', 'Cầu chữ U tại Bình Lợi là một biểu tượng kiến trúc độc đáo, nơi giao thoa giữa nhịp sống hiện đại và nét yên bình của dòng sông xanh. Đây là địa điểm yêu thích của giới trẻ để ngắm nhìn hoàng hôn buông xuống, phản chiếu ánh sáng lung linh trên mặt nước, mang lại cảm giác bình yên đến lạ kỳ.', 'Điểm ngắm hoàng hôn cực phẩm ven sông.', 'nature', '["an_nhien","thanh_loc"]', 'summer, autumn', 'Tự do', 'Miễn phí', 'none', 'Ngắm hoàng hôn và tận hưởng làn gió mát lành từ dòng sông Sài Gòn.', 'Hãy chụp ảnh tại điểm này!', '17:00 - 18:30 (Hoàng hôn)', '10.7654000', '106.5621000', 50, 50, 100, '/images/cau-chu-z-1.png', NULL, NULL, NULL, 'Cầu chữ U tại Bình Lợi là một biểu tượng kiến trúc độc đáo, nơi giao thoa giữa nhịp sống hiện đại và nét yên bình của dòng sông xanh. Đây là địa điểm yêu thích của giới trẻ để ngắm nhìn hoàng hôn buông xuống, phản chiếu ánh sáng lung linh trên mặt nước, mang lại cảm giác bình yên đến lạ kỳ.', NULL, NULL, 'SECURE_CAU-CHU-Z', 100, 0, 1, 0, '2026-06-21 03:53:04', '2026-06-21 04:43:18');
INSERT INTO `destinations` (`id`, `slug`, `name`, `description`, `short_desc`, `type`, `moods`, `seasons`, `open_hours`, `cost`, `stay_capacity`, `highlight`, `checkin_tip`, `best_time`, `lat`, `lng`, `map_x`, `map_y`, `radius_meter`, `cover_image`, `gallery`, `audio_url`, `video_url`, `story`, `zen_walk_desc`, `qr_code_url`, `qr_secret`, `points`, `is_hub`, `is_active`, `sort_order`, `created_at`, `updated_at`) VALUES ('68373127-ae7c-4b46-bf2c-90c98ed9d772', 'cong-vien-van-hoa-lang-le', 'Công viên Văn hóa Láng Le', 'Công viên Văn hóa Láng Le là một trong những không gian sinh thái tiêu biểu của huyện Bình Chánh, được hình thành với mục tiêu tạo nên khu vui chơi, giải trí và sinh hoạt cộng đồng gắn liền với cảnh quan thiên nhiên. Sở hữu diện tích rộng, nhiều cây xanh cùng hồ nước thoáng đãng, nơi đây mang đến cảm giác yên bình, tách biệt khỏi sự nhộn nhịp của khu vực trung tâm thành phố.\n\nKhông chỉ là điểm đến để nghỉ ngơi và rèn luyện sức khỏe, công viên còn là nơi diễn ra nhiều hoạt động dã ngoại, gặp gỡ bạn bè, vui chơi gia đình và các chương trình sinh hoạt ngoài trời. Những lối đi rợp bóng cây, không gian mở và bầu không khí trong lành giúp du khách dễ dàng cảm nhận nét đẹp đặc trưng của vùng ngoại thành Bình Chánh.\n\nĐến với Công viên Văn hóa Láng Le, du khách không chỉ được tận hưởng một khoảng xanh thư thái mà còn có cơ hội khám phá vẻ đẹp dung dị của thiên nhiên miền Nam, góp phần lan tỏa giá trị sống xanh và phát triển du lịch sinh thái cộng đồng tại Bình Chánh.', 'Trải nghiệm không gian xanh rộng lớn giữa lòng Bình Chánh, nơi du khách có thể dạo bộ, thư giãn, tổ chức dã ngoại, ngắm cá koi và tận hưởng bầu không khí trong lành giữa thiên nhiên.', 'nature', '[]', '[]', '07:00 - 22:00', 'Miễn phí', 'none', 'Trải nghiệm không gian xanh rộng lớn giữa lòng Bình Chánh, nơi du khách có thể dạo bộ, thư giãn, tổ chức dã ngoại, ngắm cá koi và tận hưởng bầu không khí trong lành giữa thiên nhiên.', 'Hãy chụp ảnh tại điểm này!', 'Quanh năm', '10.7780680', '106.5162224', 50, 50, 100, 'data:image/png;base64,', NULL, NULL, NULL, 'Công viên Văn hóa Láng Le là một trong những không gian sinh thái tiêu biểu của huyện Bình Chánh, được hình thành với mục tiêu tạo nên khu vui chơi, giải trí và sinh hoạt cộng đồng gắn liền với cảnh quan thiên nhiên. Sở hữu diện tích rộng, nhiều cây xanh cùng hồ nước thoáng đãng, nơi đây mang đến cảm giác yên bình, tách biệt khỏi sự nhộn nhịp của khu vực trung tâm thành phố.\n\nKhông chỉ là điểm đến để nghỉ ngơi và rèn luyện sức khỏe, công viên còn là nơi diễn ra nhiều hoạt động dã ngoại, gặp gỡ bạn bè, vui chơi gia đình và các chương trình sinh hoạt ngoài trời. Những lối đi rợp bóng cây, không gian mở và bầu không khí trong lành giúp du khách dễ dàng cảm nhận nét đẹp đặc trưng của vùng ngoại thành Bình Chánh.\n\nĐến với Công viên Văn hóa Láng Le, du khách không chỉ được tận hưởng một khoảng xanh thư thái mà còn có cơ hội khám phá vẻ đẹp dung dị của thiên nhiên miền Nam, góp phần lan tỏa giá trị sống xanh và phát triển du lịch sinh thái cộng đồng tại Bình Chánh.', NULL, NULL, 'SECURE_CONG-VIEN-VAN-HOA-LANG-LE', 100, 0, 1, 99, '2026-06-21 03:30:42', '2026-06-21 04:07:47');
INSERT INTO `destinations` (`id`, `slug`, `name`, `description`, `short_desc`, `type`, `moods`, `seasons`, `open_hours`, `cost`, `stay_capacity`, `highlight`, `checkin_tip`, `best_time`, `lat`, `lng`, `map_x`, `map_y`, `radius_meter`, `cover_image`, `gallery`, `audio_url`, `video_url`, `story`, `zen_walk_desc`, `qr_code_url`, `qr_secret`, `points`, `is_hub`, `is_active`, `sort_order`, `created_at`, `updated_at`) VALUES ('6d5170d5-eaf0-40de-b332-d767a9ee7974', 'vuon-mai', 'Vườn Mai Vàng Bình Lợi', 'Bình Lợi được mệnh danh là "Thủ phủ Mai Vàng" của miền Nam. Hàng nghìn gốc mai trải dài tít tắp tạo nên một khung cảnh thiên nhiên hùng vĩ nhưng cũng rất thơ mộng. Đặc biệt vào dịp Tết, cả vùng đất như khoác lên mình chiếc áo vàng rực rỡ, tượng trưng cho sự may mắn và thịnh vượng.', 'Thủ phủ Mai Vàng lớn nhất TP.HCM.', 'nature', '["an_nhien","kham_pha"]', 'spring', '07:00 - 18:00', '20.000đ - 50.000đ (phí tham quan)', 'none', 'Chụp ảnh check-in giữa rừng mai bạt ngàn và chọn cho mình một gốc mai ưng ý.', 'Hãy chụp ảnh tại điểm này!', 'Tháng 12 âm lịch đến Tết Nguyên Đán', '10.7601000', '106.5512000', 50, 50, 100, '/images/vuon-mai-1.png', NULL, NULL, NULL, 'Bình Lợi được mệnh danh là "Thủ phủ Mai Vàng" của miền Nam. Hàng nghìn gốc mai trải dài tít tắp tạo nên một khung cảnh thiên nhiên hùng vĩ nhưng cũng rất thơ mộng. Đặc biệt vào dịp Tết, cả vùng đất như khoác lên mình chiếc áo vàng rực rỡ, tượng trưng cho sự may mắn và thịnh vượng.', NULL, NULL, 'SECURE_VUON-MAI', 250, 0, 1, 99, '2026-06-21 03:33:51', '2026-06-21 04:20:43');
INSERT INTO `destinations` (`id`, `slug`, `name`, `description`, `short_desc`, `type`, `moods`, `seasons`, `open_hours`, `cost`, `stay_capacity`, `highlight`, `checkin_tip`, `best_time`, `lat`, `lng`, `map_x`, `map_y`, `radius_meter`, `cover_image`, `gallery`, `audio_url`, `video_url`, `story`, `zen_walk_desc`, `qr_code_url`, `qr_secret`, `points`, `is_hub`, `is_active`, `sort_order`, `created_at`, `updated_at`) VALUES ('85b71213-52f6-4687-9567-ec98b407f8cc', 'chua-phap-tang', 'Chùa Pháp Tạng', 'Chùa Pháp Tạng tọa lạc tại xã Lê Minh Xuân, huyện Bình Chánh, là một trong những điểm đến tâm linh nổi tiếng nhất khu vực. Ngôi chùa không chỉ là nơi chiêm bái của Phật tử mà còn là không gian chữa lành tâm hồn với vườn thiền và tiếng chuông chùa vang vọng. Mỗi góc nhỏ tại chùa đều mang một thông điệp về sự an nhiên và lòng nhân ái.', 'Ngôi chùa thanh tịnh với kiến trúc nghệ thuật đặc sắc.', 'temple', '["an_nhien","thanh_loc"]', 'spring, autumn', '06:00 - 21:00', 'Miễn phí', 'none', 'Tham gia khóa thiền trà và nghe thuyết pháp từ Thầy Thích Trí Huệ.', 'Hãy chụp ảnh tại điểm này!', 'Sáng sớm hoặc chiều tối', '10.7423000', '106.5312000', 50, 50, 100, '/images/chua-phap-tang-1.png', NULL, NULL, NULL, 'Chùa Pháp Tạng tọa lạc tại xã Lê Minh Xuân, huyện Bình Chánh, là một trong những điểm đến tâm linh nổi tiếng nhất khu vực. Ngôi chùa không chỉ là nơi chiêm bái của Phật tử mà còn là không gian chữa lành tâm hồn với vườn thiền và tiếng chuông chùa vang vọng. Mỗi góc nhỏ tại chùa đều mang một thông điệp về sự an nhiên và lòng nhân ái.', NULL, NULL, 'SECURE_CHUA-PHAP-TANG', 150, 0, 1, 99, '2026-06-21 03:36:14', '2026-06-21 04:20:43');
INSERT INTO `destinations` (`id`, `slug`, `name`, `description`, `short_desc`, `type`, `moods`, `seasons`, `open_hours`, `cost`, `stay_capacity`, `highlight`, `checkin_tip`, `best_time`, `lat`, `lng`, `map_x`, `map_y`, `radius_meter`, `cover_image`, `gallery`, `audio_url`, `video_url`, `story`, `zen_walk_desc`, `qr_code_url`, `qr_secret`, `points`, `is_hub`, `is_active`, `sort_order`, `created_at`, `updated_at`) VALUES ('c3f80faf-1170-47e2-9b13-0aaaed941bb1', 'rung-phong-ho', 'Rừng phòng hộ', 'Nằm tại xã Bình Lợi, huyện Bình Chánh, rừng phòng hộ mang vai trò quan trọng trong việc bảo vệ môi trường sinh thái, hạn chế xói mòn đất và điều hòa không khí cho khu vực ngoại thành. Với diện tích cây xanh rộng lớn cùng hệ thống kênh rạch tự nhiên, nơi đây tạo nên khung cảnh xanh mát, tách biệt khỏi sự ồn ào của đô thị.\nKhông chỉ có giá trị về môi trường, rừng phòng hộ Bình Lợi còn góp phần giữ gìn nét đặc trưng sinh thái của địa phương. Những con đường nhỏ xuyên qua khu vực cây xanh, không khí trong lành và vẻ đẹp hoang sơ mang lại cảm giác thư thái cho người ghé thăm. Đây cũng là nơi thể hiện sự hài hòa giữa thiên nhiên và đời sống người dân vùng ven TP.HCM, góp phần tạo nên tiềm năng phát triển du lịch sinh thái bền vững cho Bình Lợi, Bình Chánh.', 'Trải nghiệm không gian rừng sinh thái xanh mát, hít thở bầu không khí trong lành và khám phá vẻ đẹp hoang sơ của hệ sinh thái đặc trưng Bình Lợi.', 'park', '[]', '["summer","winter"]', '08:00 - 17:00', 'Miễn phí', 'none', 'Rừng phòng hộ Bình Lợi là khu vực sinh thái xanh quan trọng của huyện Bình Chánh, góp phần điều hòa môi trường, bảo vệ hệ sinh thái tự nhiên và tạo nên không gian yên bình cho vùng ngoại thành TP.HCM.', 'Hãy chụp ảnh tại điểm này!', 'Quanh năm', '10.7780680', '106.5162224', 50, 50, 100, 'data:image/png;base64,', NULL, NULL, NULL, 'Nằm tại xã Bình Lợi, huyện Bình Chánh, rừng phòng hộ mang vai trò quan trọng trong việc bảo vệ môi trường sinh thái, hạn chế xói mòn đất và điều hòa không khí cho khu vực ngoại thành. Với diện tích cây xanh rộng lớn cùng hệ thống kênh rạch tự nhiên, nơi đây tạo nên khung cảnh xanh mát, tách biệt khỏi sự ồn ào của đô thị.\r\nKhông chỉ có giá trị về môi trường, rừng phòng hộ Bình Lợi còn góp phần giữ gìn nét đặc trưng sinh thái của địa phương. Những con đường nhỏ xuyên qua khu vực cây xanh, không khí trong lành và vẻ đẹp hoang sơ mang lại cảm giác thư thái cho người ghé thăm. Đây cũng là nơi thể hiện sự hài hòa giữa thiên nhiên và đời sống người dân vùng ven TP.HCM, góp phần tạo nên tiềm năng phát triển du lịch sinh thái bền vững cho Bình Lợi, Bình Chánh.', '', NULL, 'SECURE_RUNG-PHONG-HO', 50, 0, 1, 99, '2026-05-20 11:40:19', '2026-06-21 03:42:09');
INSERT INTO `destinations` (`id`, `slug`, `name`, `description`, `short_desc`, `type`, `moods`, `seasons`, `open_hours`, `cost`, `stay_capacity`, `highlight`, `checkin_tip`, `best_time`, `lat`, `lng`, `map_x`, `map_y`, `radius_meter`, `cover_image`, `gallery`, `audio_url`, `video_url`, `story`, `zen_walk_desc`, `qr_code_url`, `qr_secret`, `points`, `is_hub`, `is_active`, `sort_order`, `created_at`, `updated_at`) VALUES ('cab3ff5d-744f-4a5e-906b-45cb52ac40a1', 'chua-thanh-tam', 'Chùa Thanh Tâm', 'Tọa lạc tại huyện Bình Chánh, TP.HCM, Chùa Thanh Tâm là một trong những điểm đến tâm linh nổi bật, được nhiều Phật tử và du khách biết đến với không gian thanh tịnh cùng kiến trúc Phật giáo trang nghiêm. Ngôi chùa còn được nhiều người gọi với tên quen thuộc là "chùa Phật cô đơn", gắn liền với hình ảnh tượng Phật uy nghi và khuôn viên rộng lớn, tách biệt khỏi sự ồn ào của đô thị.\n\nĐiểm đặc biệt của Chùa Thanh Tâm là nơi tôn trí xá lợi Phật, thu hút đông đảo Phật tử và du khách đến chiêm bái vào các dịp lễ lớn. Bên cạnh các hoạt động tín ngưỡng, chùa còn thường xuyên tổ chức lễ cầu an, các chương trình thiện nguyện và hoạt động Phật sự, góp phần lan tỏa những giá trị nhân văn và tinh thần từ bi trong cộng đồng.\n\nBao quanh chùa là hồ nước, hàng cây xanh và những lối đi yên tĩnh, tạo nên không gian lý tưởng để thiền định, thư giãn và tìm lại sự cân bằng trong cuộc sống. Đến với Chùa Thanh Tâm, du khách không chỉ được chiêm ngưỡng vẻ đẹp kiến trúc và cảnh quan thanh bình mà còn có cơ hội cảm nhận chiều sâu văn hóa, tâm linh và những giá trị truyền thống của Phật giáo giữa lòng Bình Chánh.', 'Trải nghiệm không gian tâm linh thanh tịnh, chiêm bái xá lợi Phật và tìm về sự bình an giữa khung cảnh xanh mát của Bình Chánh.', 'temple', '[]', '[]', '06:00 - 21:00', 'Miễn phí', 'none', 'Trải nghiệm không gian tâm linh thanh tịnh, chiêm bái xá lợi Phật và tìm về sự bình an giữa khung cảnh xanh mát của Bình Chánh.', 'Hãy chụp ảnh tại điểm này!', 'Quanh năm', '10.7794443', '106.5144235', 50, 50, 100, 'data:image/jpeg;base64,', NULL, NULL, NULL, 'Tọa lạc tại huyện Bình Chánh, TP.HCM, Chùa Thanh Tâm là một trong những điểm đến tâm linh nổi bật, được nhiều Phật tử và du khách biết đến với không gian thanh tịnh cùng kiến trúc Phật giáo trang nghiêm. Ngôi chùa còn được nhiều người gọi với tên quen thuộc là "chùa Phật cô đơn", gắn liền với hình ảnh tượng Phật uy nghi và khuôn viên rộng lớn, tách biệt khỏi sự ồn ào của đô thị.\n\nĐiểm đặc biệt của Chùa Thanh Tâm là nơi tôn trí xá lợi Phật, thu hút đông đảo Phật tử và du khách đến chiêm bái vào các dịp lễ lớn. Bên cạnh các hoạt động tín ngưỡng, chùa còn thường xuyên tổ chức lễ cầu an, các chương trình thiện nguyện và hoạt động Phật sự, góp phần lan tỏa những giá trị nhân văn và tinh thần từ bi trong cộng đồng.\n\nBao quanh chùa là hồ nước, hàng cây xanh và những lối đi yên tĩnh, tạo nên không gian lý tưởng để thiền định, thư giãn và tìm lại sự cân bằng trong cuộc sống. Đến với Chùa Thanh Tâm, du khách không chỉ được chiêm ngưỡng vẻ đẹp kiến trúc và cảnh quan thanh bình mà còn có cơ hội cảm nhận chiều sâu văn hóa, tâm linh và những giá trị truyền thống của Phật giáo giữa lòng Bình Chánh.', NULL, NULL, 'SECURE_CHUA-THANH-TAM', 80, 0, 1, 99, '2026-06-21 03:38:10', '2026-06-21 04:16:32');
INSERT INTO `destinations` (`id`, `slug`, `name`, `description`, `short_desc`, `type`, `moods`, `seasons`, `open_hours`, `cost`, `stay_capacity`, `highlight`, `checkin_tip`, `best_time`, `lat`, `lng`, `map_x`, `map_y`, `radius_meter`, `cover_image`, `gallery`, `audio_url`, `video_url`, `story`, `zen_walk_desc`, `qr_code_url`, `qr_secret`, `points`, `is_hub`, `is_active`, `sort_order`, `created_at`, `updated_at`) VALUES ('e61d1983-a52c-4349-959a-43455b603afb', 'dinh-go-xoai', 'Đình Gò Xoài', 'Nằm tại huyện Bình Chánh, Đình Gò Xoài là nơi thờ Thành Hoàng làng và các bậc tiền nhân có công khai phá vùng đất địa phương. Trải qua nhiều năm hình thành và phát triển, đình không chỉ là nơi sinh hoạt tín ngưỡng mà còn là không gian gắn kết cộng đồng, lưu giữ nhiều giá trị văn hóa truyền thống của người dân Nam Bộ.\nKiến trúc của đình mang nét cổ kính với mái ngói, cột gỗ và các hoa văn chạm khắc truyền thống, tạo nên không gian trang nghiêm và gần gũi. Hằng năm, các lễ hội và nghi thức cúng đình được tổ chức nhằm cầu mong quốc thái dân an, mùa màng thuận lợi và cuộc sống bình yên cho người dân. Đình Gò Xoài không chỉ phản ánh đời sống tâm linh đặc trưng của vùng quê Bình Chánh mà còn góp phần gìn giữ bản sắc văn hóa lịch sử của địa phương qua nhiều thế hệ.', 'Trải nghiệm không gian tín ngưỡng truyền thống Nam Bộ, khám phá kiến trúc cổ kính và tìm hiểu những giá trị văn hóa lâu đời của vùng đất Bình Chánh.', 'temple', '[]', '["spring","autumn"]', '08:00 - 17:00', 'Miễn phí', 'none', 'Đình Gò Xoài là công trình tín ngưỡng dân gian mang đậm nét văn hóa truyền thống Nam Bộ, gắn liền với đời sống tinh thần và lịch sử của người dân địa phương.', 'Hãy chụp ảnh tại điểm này!', 'Quanh năm', '10.7423284', '106.4973264', 50, 50, 100, 'data:image/png;base64,', NULL, NULL, NULL, 'Nằm tại huyện Bình Chánh, Đình Gò Xoài là nơi thờ Thành Hoàng làng và các bậc tiền nhân có công khai phá vùng đất địa phương. Trải qua nhiều năm hình thành và phát triển, đình không chỉ là nơi sinh hoạt tín ngưỡng mà còn là không gian gắn kết cộng đồng, lưu giữ nhiều giá trị văn hóa truyền thống của người dân Nam Bộ.\r\nKiến trúc của đình mang nét cổ kính với mái ngói, cột gỗ và các hoa văn chạm khắc truyền thống, tạo nên không gian trang nghiêm và gần gũi. Hằng năm, các lễ hội và nghi thức cúng đình được tổ chức nhằm cầu mong quốc thái dân an, mùa màng thuận lợi và cuộc sống bình yên cho người dân. Đình Gò Xoài không chỉ phản ánh đời sống tâm linh đặc trưng của vùng quê Bình Chánh mà còn góp phần gìn giữ bản sắc văn hóa lịch sử của địa phương qua nhiều thế hệ.', '', NULL, 'SECURE_DINH-GO-XOAI', 50, 0, 1, 99, '2026-05-20 11:47:18', '2026-06-21 03:40:09');
INSERT INTO `events` (`id`, `title`, `description`, `season`, `event_date`, `end_date`, `location`, `image`, `is_featured`, `is_active`, `sort_order`, `created_at`, `updated_at`, `is_countdown`, `status`) VALUES ('3a87b010-13e0-4e59-bc2e-381c1a509579', 'Lễ Hội Mùa Hè Xanh Bình Lợi', 'Sự kiện mùa hè sôi động với các hoạt động sinh thái, chèo xuồng, trải nghiệm vườn dừa, workshop làng nghề và đêm nhạc acoustic ngoài trời dành cho người dân và du khách.', 'summer', '2026-05-23 01:07:00', '2026-05-28 01:07:00', 'Công viên văn hóa Láng Le', NULL, 1, 1, 0, '2026-05-21 06:07:30', '2026-05-21 06:07:30', 0, 'upcoming');
INSERT INTO `events` (`id`, `title`, `description`, `season`, `event_date`, `end_date`, `location`, `image`, `is_featured`, `is_active`, `sort_order`, `created_at`, `updated_at`, `is_countdown`, `status`) VALUES ('72b7cf0e-56aa-4f02-b8b4-4724d2d24c1d', 'Hành Trình Xanh Rừng Phòng Hộ', 'Chương trình khám phá thiên nhiên kết hợp hoạt động trồng cây và lan tỏa ý thức bảo vệ môi trường dành cho giới trẻ và gia đình.', 'summer', '2026-05-22 01:00:00', '2026-05-23 13:01:00', 'Rừng phòng hộ', NULL, 0, 1, 0, '2026-05-21 06:01:22', '2026-05-21 06:01:22', 0, 'upcoming');
INSERT INTO `events` (`id`, `title`, `description`, `season`, `event_date`, `end_date`, `location`, `image`, `is_featured`, `is_active`, `sort_order`, `created_at`, `updated_at`, `is_countdown`, `status`) VALUES ('7f73e5a5-91cb-419c-af9b-389f47a321af', 'Đại Lễ Vu Lan Báo Hiếu', 'Chương trình văn hóa – tâm linh mang ý nghĩa tri ân cha mẹ, kết hợp lễ cầu an, thả hoa đăng và các hoạt động thiện nguyện trong không gian thanh tịnh, yên bình.', 'autumn', '2026-05-29 01:08:00', '2026-05-30 13:08:00', 'Công viên văn hóa Láng Le', NULL, 0, 1, 0, '2026-05-21 06:08:14', '2026-05-21 06:08:14', 0, 'upcoming');
INSERT INTO `events` (`id`, `title`, `description`, `season`, `event_date`, `end_date`, `location`, `image`, `is_featured`, `is_active`, `sort_order`, `created_at`, `updated_at`, `is_countdown`, `status`) VALUES ('7ffc5c72-8281-44a4-9905-8d065de6099e', 'Lễ Hội Mai Vàng Bình Lợi 2026', 'Sự kiện thường niên lớn nhất tôn vinh nghề trồng mai vàng truyền thống. Trưng bày hàng trăm gốc mai bonsai tuyệt đẹp, chợ Tết quê và các hoạt động văn hóa dân gian.', 'all', '2026-01-19 17:00:00', NULL, NULL, '/images/hero-2.png', 0, 1, 0, '2026-06-20 07:33:01', '2026-06-20 07:33:01', 0, 'upcoming');
INSERT INTO `events` (`id`, `title`, `description`, `season`, `event_date`, `end_date`, `location`, `image`, `is_featured`, `is_active`, `sort_order`, `created_at`, `updated_at`, `is_countdown`, `status`) VALUES ('85555b3f-9c54-4617-ad10-048fb159b160', 'Lễ Hội Mai Vàng Bình Lợi', 'Lễ hội đặc trưng mùa xuân với không gian trưng bày mai vàng rực rỡ, hội chợ Tết quê và các hoạt động giao lưu văn hóa truyền thống Nam Bộ. Du khách có thể tham quan vườn mai, chụp ảnh check-in và trải nghiệm không khí Tết thanh bình tại Bình Lợi, Bình Chánh.', 'spring', '2027-01-01 01:05:00', '2027-01-10 13:05:00', 'Vườn mai', NULL, 0, 1, 0, '2026-05-21 06:06:08', '2026-05-21 06:06:08', 0, 'upcoming');
INSERT INTO `events` (`id`, `title`, `description`, `season`, `event_date`, `end_date`, `location`, `image`, `is_featured`, `is_active`, `sort_order`, `created_at`, `updated_at`, `is_countdown`, `status`) VALUES ('895d9776-4046-4376-8547-8a48fc30488e', 'Đêm Nhạc Giao Thừa Láng Le', 'Chương trình nghệ thuật đặc biệt kết hợp giao lưu văn hóa, bắn pháo hoa nghệ thuật và cầu bình an đầu năm tại khu di tích.', 'all', '2026-02-15 17:00:00', NULL, NULL, '/images/hero-3.png', 0, 1, 0, '2026-06-20 07:33:01', '2026-06-20 07:33:01', 0, 'upcoming');
INSERT INTO `events` (`id`, `title`, `description`, `season`, `event_date`, `end_date`, `location`, `image`, `is_featured`, `is_active`, `sort_order`, `created_at`, `updated_at`, `is_countdown`, `status`) VALUES ('8dd8bbb6-25d3-4f47-ade4-93c9832be4f4', 'Ngày Hội Vườn Lan Bình Lợi', 'Triển lãm hoa lan, check-in giữa không gian xanh và tham gia các hoạt động chăm sóc cây cảnh cùng nghệ nhân vườn lan.', 'summer', '2026-05-21 02:00:00', '2026-05-22 10:00:00', 'Vườn lan', NULL, 0, 1, 0, '2026-05-21 06:00:04', '2026-05-21 06:00:04', 0, 'upcoming');
INSERT INTO `events` (`id`, `title`, `description`, `season`, `event_date`, `end_date`, `location`, `image`, `is_featured`, `is_active`, `sort_order`, `created_at`, `updated_at`, `is_countdown`, `status`) VALUES ('a3380ea4-059f-4446-9c43-7ba3ee2a5b2a', 'Ngày Hội Nông Sản Xanh', 'Gặp gỡ những người nông dân địa phương, trải nghiệm thu hoạch trái cây, thưởng thức đặc sản tươi sống và tham gia workshop làm nông.', 'all', '2026-06-14 17:00:00', NULL, NULL, '/images/hero-1.png', 0, 1, 0, '2026-06-20 07:33:02', '2026-06-20 07:33:02', 0, 'upcoming');
INSERT INTO `festivals` (`id`, `name`, `date`, `description`, `image`, `status`) VALUES ('7ffc5c72-8281-44a4-9905-8d065de6099e', 'Lễ Hội Mai Vàng Bình Lợi 2026', '2026-01-19 17:00:00', 'Sự kiện thường niên lớn nhất tôn vinh nghề trồng mai vàng truyền thống. Trưng bày hàng trăm gốc mai bonsai tuyệt đẹp, chợ Tết quê và các hoạt động văn hóa dân gian.', '/images/hero-2.png', 'upcoming');
INSERT INTO `festivals` (`id`, `name`, `date`, `description`, `image`, `status`) VALUES ('895d9776-4046-4376-8547-8a48fc30488e', 'Đêm Nhạc Giao Thừa Láng Le', '2026-02-15 17:00:00', 'Chương trình nghệ thuật đặc biệt kết hợp giao lưu văn hóa, bắn pháo hoa nghệ thuật và cầu bình an đầu năm tại khu di tích.', '/images/hero-3.png', 'upcoming');
INSERT INTO `festivals` (`id`, `name`, `date`, `description`, `image`, `status`) VALUES ('a3380ea4-059f-4446-9c43-7ba3ee2a5b2a', 'Ngày Hội Nông Sản Xanh', '2026-06-14 17:00:00', 'Gặp gỡ những người nông dân địa phương, trải nghiệm thu hoạch trái cây, thưởng thức đặc sản tươi sống và tham gia workshop làm nông.', '/images/hero-1.png', 'upcoming');
