INSERT INTO `seasonal_journey_templates` (`id`, `name`, `description`, `season`, `interest`, `stops`, `duration`, `km`, `created_at`, `updated_at`) VALUES ('09e4f2f1-9da4-4f82-9a3f-6bb31d197f45', 'Hơi Thở Mùa Hè Xanh', 'Trải nghiệm mùa hè sinh thái với vườn dừa, hoạt động sông nước và không gian thiên nhiên xanh mát đặc trưng của Bình Lợi.', 'summer', 'peace', '["27d4d05c-3d48-4d05-922b-752cf22b3a3c","fb45b011-562b-4510-aeba-76755543ed86","c3f80faf-1170-47e2-9b13-0aaaed941bb1","0ab82769-3690-434e-a5ee-4f163e150552"]', 'full_day', '6.80', '2026-05-21 06:12:35', '2026-05-21 06:12:35');
INSERT INTO `seasonal_journey_templates` (`id`, `name`, `description`, `season`, `interest`, `stops`, `duration`, `km`, `created_at`, `updated_at`) VALUES ('1bd50f09-1e88-4607-9ac2-5005b90921df', 'Du Xuân Đất Tổ Bình Lợi', 'Hành trình khám phá vẻ đẹp mùa xuân Bình Lợi với không gian mai vàng rực rỡ, làng nghề truyền thống và nét văn hóa tâm linh đầu năm tại Bình Chánh.', 'spring', 'chill', '["1afb3596-b67b-47e8-8594-82ad1c7b9981","3ec7a849-930c-42c1-897b-57238908061e","554a130e-286f-401e-9990-14806507af47","0ab82769-3690-434e-a5ee-4f163e150552"]', 'full_day', '5.20', '2026-05-21 06:11:16', '2026-05-21 06:11:16');
INSERT INTO `seasonal_journey_templates` (`id`, `name`, `description`, `season`, `interest`, `stops`, `duration`, `km`, `created_at`, `updated_at`) VALUES ('44729893-6a31-4207-bea5-ee47f0ff72d6', 'Thu An Yên', 'Hành trình chữa lành mùa thu với không gian thiền, lễ Vu Lan và thiên nhiên yên bình giúp du khách tìm lại sự cân bằng.', 'autumn', 'peace', '["554a130e-286f-401e-9990-14806507af47","80e0ea08-67d4-428e-b341-4db9b0d4f8d5","c3f80faf-1170-47e2-9b13-0aaaed941bb1"]', 'half_day', '4.10', '2026-05-21 06:13:57', '2026-05-21 06:13:57');
INSERT INTO `seasonal_journey_templates` (`id`, `name`, `description`, `season`, `interest`, `stops`, `duration`, `km`, `created_at`, `updated_at`) VALUES ('f9104238-e7ae-47d7-b7ff-32020a157e3f', 'Chạm Vào Bình Yên', 'Hành trình cuối năm mang đậm không khí miền quê Nam Bộ với hội chợ quê, ẩm thực dân gian và các hoạt động văn hóa cộng đồng.', 'winter', 'culture', '["0ab82769-3690-434e-a5ee-4f163e150552","20716b9e-784d-4ff1-ada1-28e9faee8696","3ec7a849-930c-42c1-897b-57238908061e","fb45b011-562b-4510-aeba-76755543ed86"]', 'full_day', '5.70', '2026-05-21 06:16:05', '2026-05-21 06:16:05');
