INSERT INTO `workshops` (`id`, `destination_id`, `title`, `description`, `type`, `price`, `max_participants`, `duration_minutes`, `schedule_note`, `image`, `is_active`, `sort_order`, `created_at`, `updated_at`, `start_date`, `end_date`, `duration`) VALUES ('110ff6fc-9055-4bec-abbb-2465e2ff0353', '3ec7a849-930c-42c1-897b-57238908061e', 'Hương Sắc Làng Nhang', 'Trải nghiệm quy trình làm nhang thủ công truyền thống từ se tăm, nhuộm chân nhang đến phơi nhang. Du khách sẽ được tìm hiểu nét đẹp văn hóa tâm linh và nghề thủ công lâu đời của người dân Bình Lợi, Bình Chánh.', 'nhang', 50000, 20, 60, NULL, 'data:image/png;base64,', 1, 0, '2026-05-20 12:30:17', '2026-05-21 05:39:49', '2026-05-20 14:00:00', '2026-05-30 05:30:00', '60 phút');
INSERT INTO `workshops` (`id`, `destination_id`, `title`, `description`, `type`, `price`, `max_participants`, `duration_minutes`, `schedule_note`, `image`, `is_active`, `sort_order`, `created_at`, `updated_at`, `start_date`, `end_date`, `duration`) VALUES ('b220208b-5c35-4d4b-a751-ab03ceff65ee', '20716b9e-784d-4ff1-ada1-28e9faee8696', 'Sắc hoa lan', 'Workshop hướng dẫn chăm sóc hoa lan, tìm hiểu các giống lan đặc trưng và trải nghiệm không gian xanh thư giãn tại vườn lan Bình Lợi.', 'ecology', 60000, 30, 60, NULL, 'data:image/png;base64,', 1, 0, '2026-05-21 05:52:34', '2026-05-21 06:20:42', '2026-05-20 00:00:00', '2026-05-30 10:00:00', '60 phút');
INSERT INTO `workshops` (`id`, `destination_id`, `title`, `description`, `type`, `price`, `max_participants`, `duration_minutes`, `schedule_note`, `image`, `is_active`, `sort_order`, `created_at`, `updated_at`, `start_date`, `end_date`, `duration`) VALUES ('d06806c0-f4ab-48b8-b7b2-8c860f75e547', '27d4d05c-3d48-4d05-922b-752cf22b3a3c', 'Vị Ngọt Vườn Dừa', 'Du khách sẽ được trải nghiệm hái dừa, thưởng thức nước dừa tươi và khám phá nét đẹp miệt vườn đặc trưng của Bình Lợi, Bình Chánh.', 'ecology', 50000, 40, 60, NULL, 'data:image/png;base64,', 1, 0, '2026-05-21 05:49:29', '2026-05-21 05:49:29', '2026-05-20 02:00:00', '2026-05-30 10:00:00', '1 giờ 30 phút');
